import { Injectable, Logger, Inject, BadRequestException } from "@nestjs/common";
import { TRANSACTION_REPOSITORY } from "../../domain/repositories/transaction.repository.interface.js";
import type { ITransactionRepository } from "../../domain/repositories/transaction.repository.interface.js";

import { TransferResponse } from "../dto/transfer-funds.dto.js";

@Injectable()
export class GetTransferByUserUseCase {
  private readonly logger = new Logger(GetTransferByUserUseCase.name);
  constructor(
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
  ) {}

  async execute(userId: string): Promise<TransferResponse[]> {
    if (!userId) {
      throw new BadRequestException("El userId es requerido para obtener las transferencias.");
    }

    this.logger.log(
      `Procesando obtener transferencias del usuario ${userId}...`,
    );

    try {
      const transactions =
        await this.transactionRepository.getTransfersByUser(userId);
      this.logger.log(
        `[EXITO] Transferencias del usuario ${userId} obtenidas correctamente.`,
      );
      return transactions.map((t) => ({
        transactionId: t.getId(),
        fromAccountId: t.getFromAccountId(),
        toAccountId: t.getToAccountId(),
        amount: t.getAmount(),
        status: t.getStatus(),
      }));
    } catch (error: any) {
      this.logger.error(
        `[FALLO] No se pudo obtener las transferencias del usuario ${userId}: ${error.message}`,
      );
      // En un sistema real aquí se marca el depósito como FAILED en la base de datos o
      // se lanza una excepción para que RabbitMQ lo vuelva a encolar y reintentar si es 503.
      throw error;
    }
  }
}
