import { Injectable } from '@nestjs/common';
import { ITransactionRepository } from '../../domain/repositories/transaction.repository.interface.js';
import { PrismaClient } from '@prisma/client-accounts';
import { Transaction } from '../../domain/entities/transaction.entity.js';
import { Account } from '@app/account';

@Injectable()
export class PrismaTransactionRepository implements ITransactionRepository {
  private prisma = new PrismaClient();

  async processDeposit(depositId: string, accountId: string, amount: number): Promise<void> {
    await this.prisma.$transaction(async (tx) => {
      const accountRecord = await tx.account.findUniqueOrThrow({
        where: { id: accountId },
      });

      const account = Account.load(
        accountRecord.id,
        accountRecord.accountNumber,
        accountRecord.bank,
        accountRecord.userId,
        accountRecord.balance,
        accountRecord.status as any,
        accountRecord.type as any,
        accountRecord.createdAt,
        accountRecord.version,
      );

      account.deposit(amount);

      const updated = await tx.account.updateMany({
        where: {
          id: account.getId(),
          version: accountRecord.version,
        },
        data: {
          balance: account.getBalance(),
          version: { increment: 1 },
        },
      });

      if (updated.count === 0) {
        throw new Error("Concurrency Error during deposit");
      }
    });
  }

  async processTransfer(transaction: Transaction): Promise<void> {
    await this.prisma.$transaction(async (tx) => {
      const fromAccountRecord = await tx.account.findUniqueOrThrow({ where: { id: transaction.getFromAccountId() } });
      const toAccountRecord = await tx.account.findUniqueOrThrow({ where: { id: transaction.getToAccountId() } });

      const fromAccount = Account.load(
        fromAccountRecord.id, 
        fromAccountRecord.accountNumber,
        fromAccountRecord.bank,
        fromAccountRecord.userId, 
        fromAccountRecord.balance,
        fromAccountRecord.status as any,
        fromAccountRecord.type as any,
        fromAccountRecord.createdAt,
        fromAccountRecord.version
      );
      
      const toAccount = Account.load(
        toAccountRecord.id, 
        toAccountRecord.accountNumber,
        toAccountRecord.bank,
        toAccountRecord.userId, 
        toAccountRecord.balance,
        toAccountRecord.status as any,
        toAccountRecord.type as any,
        toAccountRecord.createdAt,
        toAccountRecord.version
      );

      fromAccount.withdraw(transaction.getAmount());
      toAccount.deposit(transaction.getAmount());

      const updatedFrom = await tx.account.updateMany({
        where: {
          id: fromAccount.getId(),
          version: fromAccountRecord.version,
        },
        data: {
          balance: fromAccount.getBalance(),
          version: { increment: 1 },
        },
      });

      if (updatedFrom.count === 0) {
        throw new Error('Concurrency Error: Account balance was modified by another process. Please retry.');
      }

      await tx.account.update({
        where: { id: toAccount.getId() },
        data: {
          balance: toAccount.getBalance(),
          version: { increment: 1 },
        },
      });

      await tx.outboxEvent.create({
        data: {
          aggregateId: transaction.getId(),
          type: 'FUNDS_TRANSFERRED',
          payload: {
            fromAccountId: transaction.getFromAccountId(),
            toAccountId: transaction.getToAccountId(),
            amount: transaction.getAmount(),
          },
        },
      });
    });
  }

  async getTransfersByUser(userId: string): Promise<Transaction[]> {
    // 1. Obtener todas las cuentas del usuario
    const userAccounts = await this.prisma.account.findMany({
      where: { userId },
      select: { id: true },
    });
    
    if (userAccounts.length === 0) {
      return [];
    }

    const accountIds = userAccounts.map(a => a.id);

    // 2. Dado que no tenemos una tabla 'TransactionHistory' per se, usamos OutboxEvent 
    // como nuestro "Source of Truth" de auditoría de transacciones para el PoC.
    // En PostgreSQL podemos consultar el JSON directamente, pero para simplicidad filtramos en memoria 
    // si el set de datos es pequeño (o usamos RAW queries en Prisma).
    const events = await this.prisma.outboxEvent.findMany({
      where: { type: 'FUNDS_TRANSFERRED' },
      orderBy: { createdAt: 'desc' }
    });

    const userEvents = events.filter(e => {
      const payload = e.payload as any;
      return accountIds.includes(payload.fromAccountId) || accountIds.includes(payload.toAccountId);
    });

    return userEvents.map(e => {
      const payload = e.payload as any;
      const t = Transaction.create(e.aggregateId, payload.fromAccountId, payload.toAccountId, payload.amount);
      t.markAsCompleted();
      return t;
    });
  }

  async getPendingOutboxEvents(): Promise<{ id: string, type: string, payload: any }[]> {
    return this.prisma.outboxEvent.findMany({
      where: { status: 'PENDING' },
      take: 50, // Procesar en lotes
      orderBy: { createdAt: 'asc' }
    });
  }

  async markOutboxEventAsPublished(eventId: string): Promise<void> {
    await this.prisma.outboxEvent.update({
      where: { id: eventId },
      data: { status: 'PUBLISHED' }
    });
  }
}
