export type DepositStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export class Deposit {
  private constructor(
    private readonly id: string,
    private readonly accountId: string,
    private readonly amount: number,
    private readonly idempotencyKey: string,
    private status: DepositStatus,
    private readonly createdAt: Date,
    private updatedAt: Date,
  ) {}

  static create(id: string, accountId: string, amount: number, idempotencyKey: string): Deposit {
    if (amount <= 0) {
      throw new Error('Deposit amount must be strictly positive');
    }
    if (!idempotencyKey) {
      throw new Error('Idempotency key is required to prevent double charging');
    }
    return new Deposit(id, accountId, amount, idempotencyKey, 'PENDING', new Date(), new Date());
  }

  approve(): void {
    if (this.status !== 'PENDING') {
      throw new Error('Can only approve pending deposits');
    }
    this.status = 'APPROVED';
    this.updatedAt = new Date();
  }

  reject(): void {
    if (this.status !== 'PENDING') {
      throw new Error('Can only reject pending deposits');
    }
    this.status = 'REJECTED';
    this.updatedAt = new Date();
  }

  // Getters
  getId(): string { return this.id; }
  getAccountId(): string { return this.accountId; }
  getAmount(): number { return this.amount; }
  getIdempotencyKey(): string { return this.idempotencyKey; }
  getStatus(): DepositStatus { return this.status; }
}
