import { Injectable, Logger, Inject } from "@nestjs/common";
import { BankApiService } from "../../infrastructure/external/bank-api.service.js";
import { TRANSACTION_REPOSITORY } from "../../domain/repositories/transaction.repository.interface.js";
import type { ITransactionRepository } from "../../domain/repositories/transaction.repository.interface.js";
import { BrokerEvents } from "@app/shared";
import { EVENT_BUS_PORT } from "../../domain/interfaces/event-bus.interface.js";
import type { IEventBus } from "../../domain/interfaces/event-bus.interface.js";

@Injectable()
export class ProcessDepositUseCase {
  private readonly logger = new Logger(ProcessDepositUseCase.name);
  constructor(
    @Inject(BankApiService)
    private readonly bankApiService: BankApiService,
    @Inject(EVENT_BUS_PORT) private readonly eventBus: IEventBus,
    @Inject(TRANSACTION_REPOSITORY)
    private readonly transactionRepository: ITransactionRepository,
  ) {}

  async execute(
    depositId: string,
    accountId: string,
    amount: number,
    cardToken: string,
  ): Promise<void> {
    this.logger.log(
      `Procesando depósito ${depositId} para la cuenta ${accountId}...`,
    );

    try {
      // 1. Llamar al API externa inestable (Esto tomará 5-15 segundos)
      await this.bankApiService.processDeposit(amount, cardToken);

      // 2. Si llegamos hasta aquí, el banco cobró con éxito la tarjeta.
      // Ahora debemos acreditar el saldo en la base de datos de manera atómica.
      await this.transactionRepository.processDeposit(
        depositId,
        accountId,
        amount,
      );

      this.logger.log(
        `[EXITO] Depósito ${depositId} completado. Saldo acreditado a ${accountId}.`,
      );

      // Emitir evento asíncrono para notificaciones
      await this.eventBus.emitEvent(BrokerEvents.DEPOSIT_COMPLETED, {
        depositId,
        accountId,
        amount,
      });
    } catch (error: any) {
      this.logger.error(
        `[FALLO] No se pudo completar el depósito ${depositId}: ${error.message}`,
      );
      // En un sistema real aquí se marca el depósito como FAILED en la base de datos o
      // se lanza una excepción para que RabbitMQ lo vuelva a encolar y reintentar si es 503.
      throw error;
    }
  }
}
