import {
  Controller,
  Post,
  Body,
  Inject,
  HttpCode,
  HttpStatus,
  Get,
  Query,
  ParseUUIDPipe,
  UseGuards,
  Req,
  UseInterceptors,
} from "@nestjs/common";
import {
  TransferFundsDto,
  RequestDepositDto,
  DepositRequestedResponse,
  GetTransferByUserUseCase,
  GetTransferByUserDto,
} from "@app/transaction";
import { TransferFundsUseCase } from "@app/transaction";
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiHeader } from "@nestjs/swagger";
import { ClientProxy } from "@nestjs/microservices";
import { BrokerEvents, JwtAuthGuard, IdempotencyInterceptor } from "@app/shared";
import { randomUUID } from "crypto";

@ApiTags("Transactions")
@ApiBearerAuth('JWT-auth')
@UseGuards(JwtAuthGuard)
@Controller("api/v1/transactions")
export class TransactionsController {
  constructor(
    @Inject(TransferFundsUseCase)
    private readonly transferFundsUseCase: TransferFundsUseCase,
    private readonly getTransfersByUserUseCase: GetTransferByUserUseCase,
    @Inject("RABBITMQ_SERVICE") private readonly rabbitClient: ClientProxy,
  ) {}

  @Post("transfer")
  @UseInterceptors(IdempotencyInterceptor)
  @ApiHeader({ name: 'x-idempotency-key', description: 'Unique UUID to prevent duplicate transfers', required: true })
  @ApiOperation({ summary: "Transfer funds between two accounts (P2P)" })
  @ApiResponse({
    status: 201,
    description: "The transfer was successful and is pending clearing.",
  })
  @ApiResponse({
    status: 400,
    description: "Insufficient funds or inactive accounts.",
  })
  async transferFunds(@Body() dto: TransferFundsDto) {
    try {
      const transaction = await this.transferFundsUseCase.execute(dto);
      return {
        message: "Transfer successful",
        data: {
          id: transaction.toAccountId,
          amount: transaction.amount,
          status: transaction.status,
        },
      };
    } catch (error: any) {
      return {
        message: "Transfer failed",
        error: error.message,
      };
    }
  }

  @Post("deposit")
  @UseInterceptors(IdempotencyInterceptor)
  @ApiHeader({ name: 'x-idempotency-key', description: 'Unique UUID to prevent duplicate deposits', required: true })
  @HttpCode(HttpStatus.ACCEPTED) // 202 Accepted indica que la petición se recibió pero no se ha completado
  @ApiOperation({ summary: "Request a deposit using an external Bank API" })
  @ApiResponse({
    status: 202,
    description:
      "Deposit request accepted and is being processed in background.",
  })
  @ApiResponse({ status: 400, description: "Bad Request." })
  async requestDeposit(
    @Body() dto: RequestDepositDto,
  ): Promise<DepositRequestedResponse> {
    const depositId = randomUUID();

    // Emitimos el evento asíncrono hacia RabbitMQ
    this.rabbitClient.emit(BrokerEvents.DEPOSIT_REQUESTED, {
      depositId,
      accountId: dto.accountId,
      amount: dto.amount,
      cardToken: dto.cardToken,
    });

    // Respondemos inmediatamente sin esperar al banco
    return {
      message:
        "Tu depósito está siendo procesado por el banco. Te notificaremos cuando se complete.",
      depositId,
      status: "PENDING",
    };
  }

  @Get("transfers-by-user")
  @ApiOperation({ summary: "Get transfers by user" })
  @ApiResponse({ status: 200, description: "List of transfers" })
  async getTransfersByUser(
    @Req() req: any,
  ) {
    try {
      const userId = req.user.id; // Extraído de forma segura desde el JWT
      const transactions = await this.getTransfersByUserUseCase.execute(userId);
      return { data: transactions };
    } catch (error: any) {
      return { data: [], error: error.message };
    }
  }
}
